        cat,tag=9,'Conversation and ideas'
        for needles,c,t in mapping:
            if any(x in tags for x in needles): cat,tag=c,t; break
        typ=matches[0][1].get('type') if matches else None
        pos={1:'verb',2:'noun',3:'adjective',4:'adverb',5:'function word'}.get(typ,'mixed')
